+    for (NSUInteger i = 0; i < data.length; i++) {
+        [s appendFormat:@"%02x", bytes[i]];
+    }
+    return s;
+}
+
+static NSData *aesDecrypt(NSData *cipher, NSData *key, NSData *iv) {
+    size_t outLength = cipher.length + kCCBlockSizeAES128;
+    void *outBytes = malloc(outLength);
+    size_t numBytesOut = 0;
+    CCCryptorStatus status = CCCrypt(kCCDecrypt, kCCAlgorithmAES, kCCOptionPKCS7Padding,
