+        free(outBytes);
+        fprintf(stderr, "AES decrypt failed: %d\n", (int)status);
+        return nil;
+    }
+    return [NSData dataWithBytesNoCopy:outBytes length:numBytesOut freeWhenDone:YES];
+}
+
+static void dumpObject(id obj) {
